(()=>{'use strict';const $=id=>document.getElementById(id);const results=document.querySelector('.results');
document.querySelector('.lede').textContent='Start with your household, choose your supply goal, then open only the topics you need. Download your shopping list and plan when you’re ready.';
document.querySelector('.top nav').innerHTML='<a href="#household-card">Household</a><a href="#topic-cards">Your topics</a><a href="#final-plan" class="button dark">Final plan & PDF</a>';
const setup=document.querySelector('.setup');const settings=document.createElement('details');settings.id='household-card';settings.className='middle-setup';settings.open=true;settings.innerHTML='<summary><span class="middle-step">START HERE</span><strong>Your household</strong><span id="middle-household-summary">People, location and priorities</span><span class="middle-expand">Edit settings</span></summary>';
setup.before(settings);settings.append(setup);const done=document.createElement('button');done.className='dark middle-setup-done';done.type='button';done.textContent='Use these details · review my plan';setup.append(done);done.onclick=()=>{settings.open=false;document.querySelector('.results').scrollIntoView({behavior:'smooth',block:'start'});$('middle-topics-heading').focus({preventScroll:true})};
const next=document.querySelector('.next');const nextLink=document.createElement('a');nextLink.href='#topic-cards';nextLink.className='button';nextLink.textContent='Explore topics';next.append(nextLink);document.querySelector('.step-arrow').hidden=true;
const intro=document.createElement('div');intro.className='middle-topics-intro';intro.id='topic-cards';intro.innerHTML='<p class="eyebrow">EXPLORE ONE TOPIC AT A TIME</p><h2 id="middle-topics-heading" tabindex="-1">Your plan, in manageable pieces.</h2><p>Select a card to open its guidance and checklist right here. Open another to switch topics.</p>';
const grid=document.createElement('div');grid.className='middle-grid';results.insertBefore(intro,$('buying-guide'));intro.after(grid);
const stash=document.createElement('div');stash.hidden=true;results.append(stash);stash.append($('buying-guide'));
let printing=false;window.addEventListener('beforeprint',()=>printing=true);window.addEventListener('afterprint',()=>printing=false);const cards=new Map();
function card(id,title,desc,kind,contents){const d=document.createElement('details');d.id='middle-'+id;d.className='middle-card '+kind;d.innerHTML=`<summary><span class="middle-card-heading"><span class="middle-category">${kind==='green'?'SUPPLIES':kind==='blue'?'CARE & CONNECTION':kind==='amber'?'ACTION & EQUIPMENT':'HOUSEHOLD PLAN'}</span><strong>${title}</strong><span class="middle-card-desc">${desc}</span></span><span class="middle-plus" aria-hidden="true">+</span><span class="middle-open-label">Open section</span></summary><div class="middle-card-body"></div>`;for(const node of contents||[])if(node)d.lastElementChild.append(node);d.addEventListener('toggle',()=>{d.querySelector('.middle-open-label').textContent=d.open?'Close section':'Open section';if(d.open&&!printing){for(const other of cards.values())if(other!==d)other.open=false}});grid.append(d);cards.set(id,d);return d.lastElementChild}
const familyBody=card('family','Children’s play & learning','Pack age-appropriate supplies and plan for school closures.','amber',[]);
familyBody.id='family-learning';
const water=card('water','Water & cleanup','Storage amounts, safe containers and practical cleanup supplies.','green',[]);
const food=card('food','Food & meal planning','Specific foods, household quantities and easy meal examples.','green',[]);
card('medical','Medical & first aid','OTC supplies, prescription continuity, training and inventory.','blue',[$('medical-module')]);
card('power','Power & lighting','Lights, phone charging, solar stations and your device calculator.','amber',[$('starter-power'),$('portable-power'),$('power-planner')]);
card('communications','Communications','Emergency radios, family check-ins and trusted-contact codes.','blue',[$('comms-panel')]);
const home=card('home','Home, travel & special needs','Evacuation, vehicle supplies, household safety and other buying guides.','sage',[]);
card('checklist','Your action checklist','Track To do, Done and Not needed across your whole plan.','amber',[document.querySelector('.checklist')]);
card('notes','Notes & references','Meeting points, responsibilities, review dates and source guides.','sage',[$('notes').closest('section'),document.querySelector('.resources')]);
next.remove();intro.before(next);intro.before($('final-plan'));
const previewSummary=document.createElement('p');previewSummary.className='middle-pdf-caption';previewSummary.textContent='Your take-home result: a specific shopping checklist plus practical guidance. You can export while tasks are unfinished.';$('final-heading').after(previewSummary);
const preview=$('plan-preview'),pdfDetails=document.createElement('details');pdfDetails.className='middle-pdf-preview';pdfDetails.innerHTML='<summary>See what your PDF includes</summary>';preview.before(pdfDetails);pdfDetails.append(preview);
function syncGuides(){const groups={water:[],food:[],home:[]};for(const d of $('buying-topics').children){const t=d.querySelector('summary')?.textContent.toLowerCase()||'';const key=/water|cleanup/.test(t)?'water':/food|meal/.test(t)?'food':'home';const c=d.cloneNode(true);c.open=[...({water,food,home}[key]).querySelectorAll('details[open]')].some(old=>old.dataset.topic===d.dataset.topic);groups[key].push(c)}for(const [key,body]of [['water',water],['food',food],['home',home]])body.replaceChildren(...groups[key]);$('middle-household-summary').textContent=$('household-summary').textContent+' · '+$('experience').selectedOptions[0].textContent.split(' · ')[0];}
window.addEventListener('middleupdated',()=>{if(!printing)syncGuides()});window.addEventListener('afterprint',syncGuides);syncGuides();window.dispatchEvent(new Event('familyready'));
function revealHash(){let id=decodeURIComponent(location.hash.slice(1));if(id==='buying-guide')id='middle-water';if(!id)return;const target=document.getElementById(id);if(!target)return;let p=target;while(p){if(p.tagName==='DETAILS')p.open=true;p=p.parentElement}requestAnimationFrame(()=>target.scrollIntoView({block:'start'}))}
window.addEventListener('hashchange',revealHash);revealHash();
window.addEventListener('beforeprint',()=>{for(const d of cards.values())d.dataset.wasOpen=String(d.open)});
})();
